import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"Class: SessionManager","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: SessionManager"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/prismarine/classes/SessionManager"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/prismarine/classes/SessionManager"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/prismarine/src"}},"headers":[],"relativePath":"api/@jsprismarine/prismarine/classes/SessionManager.md","filePath":"api/@jsprismarine/prismarine/classes/SessionManager.md","lastUpdated":1794472814000}`),a={name:`api/@jsprismarine/prismarine/classes/SessionManager.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/prismarine</a> / SessionManager</p><h1 id="class-sessionmanager" tabindex="-1">Class: SessionManager <a class="header-anchor" href="#class-sessionmanager" aria-label="Permalink to “Class: SessionManager”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L23" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:23</a></p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new SessionManager</strong>(): <code>SessionManager</code></p></blockquote><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>SessionManager</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="add" tabindex="-1">add() <a class="header-anchor" href="#add" aria-label="Permalink to “add()”">​</a></h3><blockquote><p><strong>add</strong>(<code>id</code>, <code>connection</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L34" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:34</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id" tabindex="-1">id <a class="header-anchor" href="#id" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><h5 id="connection" tabindex="-1">connection <a class="header-anchor" href="#connection" aria-label="Permalink to “connection”">​</a></h5><p><code>ClientConnection</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="claimidentity" tabindex="-1">claimIdentity() <a class="header-anchor" href="#claimidentity" aria-label="Permalink to “claimIdentity()”">​</a></h3><blockquote><p><strong>claimIdentity</strong>(<code>connection</code>, <code>identity</code>, <code>joined</code>): <code>ReplacedLogin</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L89" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:89</a></p><p>Takes <code>identity</code> for <code>connection</code> and hands back every other connection that holds the same account, so the caller can disconnect them.</p><p>A match is any connection that reserved a matching account, at any phase from the login to the spawn, and any connection whose player matches, for a player that joined without a reservation. Each match loses its reservation here, so its own login stops at its next <a href="#holdsidentity">SessionManager.holdsIdentity</a> check.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="connection-1" tabindex="-1">connection <a class="header-anchor" href="#connection-1" aria-label="Permalink to “connection”">​</a></h5><p><code>ClientConnection</code></p><p>The connection whose login is being let in.</p><h5 id="identity" tabindex="-1">identity <a class="header-anchor" href="#identity" aria-label="Permalink to “identity”">​</a></h5><p><code>PlayerIdentity</code></p><p>The account its login names.</p><h5 id="joined" tabindex="-1">joined <a class="header-anchor" href="#joined" aria-label="Permalink to “joined”">​</a></h5><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>Settles when this connection&#39;s join has finished or failed.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>ReplacedLogin</code>[]</p><p>The connections to replace, oldest reservation first.</p><hr><h3 id="findplayer" tabindex="-1">findPlayer() <a class="header-anchor" href="#findplayer" aria-label="Permalink to “findPlayer()”">​</a></h3><blockquote><p><strong>findPlayer</strong>(<code>query</code>): <code>StorePlayer</code> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L192" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:192</a></p><p>The online player with this name or XUID.</p><p>Sees only players who finished joining. A login looks for the sessions it replaces through <a href="#claimidentity">SessionManager.claimIdentity</a> instead, which also sees one still joining.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="query" tabindex="-1">query <a class="header-anchor" href="#query" aria-label="Permalink to “query”">​</a></h5><p>The name or XUID to look for.</p><h6 id="name" tabindex="-1">name? <a class="header-anchor" href="#name" aria-label="Permalink to “name?”">​</a></h6><p><code>string</code></p><p>The display name.</p><h6 id="xuid" tabindex="-1">xuid? <a class="header-anchor" href="#xuid" aria-label="Permalink to “xuid?”">​</a></h6><p><code>string</code></p><p>The Xbox Live id.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>StorePlayer</code> | <code>null</code></p><p>The player, or null when no online player matches.</p><hr><h3 id="findsession" tabindex="-1">findSession() <a class="header-anchor" href="#findsession" aria-label="Permalink to “findSession()”">​</a></h3><blockquote><p><strong>findSession</strong>(<code>query</code>): <a href="./PlayerSession.html"><code>PlayerSession</code></a> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L165" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:165</a></p><p>The session of the online player whose login named this name or XUID, matched against the identity each session holds.</p><p>Sees only players who finished joining, as <a href="#findplayer">SessionManager.findPlayer</a> does.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="query-1" tabindex="-1">query <a class="header-anchor" href="#query-1" aria-label="Permalink to “query”">​</a></h5><p>The name or XUID to look for.</p><h6 id="name-1" tabindex="-1">name? <a class="header-anchor" href="#name-1" aria-label="Permalink to “name?”">​</a></h6><p><code>string</code></p><p>The display name.</p><h6 id="xuid-1" tabindex="-1">xuid? <a class="header-anchor" href="#xuid-1" aria-label="Permalink to “xuid?”">​</a></h6><p><code>string</code></p><p>The Xbox Live id. An empty one names no account and matches nobody.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./PlayerSession.html"><code>PlayerSession</code></a> | <code>null</code></p><p>The session, or null when no online player matches.</p><hr><h3 id="get" tabindex="-1">get() <a class="header-anchor" href="#get" aria-label="Permalink to “get()”">​</a></h3><blockquote><p><strong>get</strong>(<code>id</code>): <code>ClientConnection</code> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L42" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:42</a></p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id-1" tabindex="-1">id <a class="header-anchor" href="#id-1" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>ClientConnection</code> | <code>null</code></p><hr><h3 id="getallplayers" tabindex="-1">getAllPlayers() <a class="header-anchor" href="#getallplayers" aria-label="Permalink to “getAllPlayers()”">​</a></h3><blockquote><p><strong>getAllPlayers</strong>(): <code>StorePlayer</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L127" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:127</a></p><p>Every player on the server, in any world.</p><p>Online only, the same test <code>World.getViewers</code> applies. A connection has a session from the moment it authenticates, well before the client is ready to be sent anything, and without this the login handshake was among the recipients of every broadcast.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>StorePlayer</code>[]</p><p>The online players&#39; store players, in the order of <a href="#getsessions">SessionManager.getSessions</a>.</p><hr><h3 id="getplayerbyexactname" tabindex="-1"><s>getPlayerByExactName()</s> <a class="header-anchor" href="#getplayerbyexactname" aria-label="Permalink to “getPlayerByExactName()”">​</a></h3><blockquote><p><strong>getPlayerByExactName</strong>(<code>name</code>): <code>StorePlayer</code> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L203" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:203</a></p><p>Just a compatibility layer to not break everything for now</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="name-2" tabindex="-1">name <a class="header-anchor" href="#name-2" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>StorePlayer</code> | <code>null</code></p><h4 id="deprecated" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated" aria-label="Permalink to “Deprecated”">​</a></h4><hr><h3 id="getplayerbyid" tabindex="-1"><s>getPlayerById()</s> <a class="header-anchor" href="#getplayerbyid" aria-label="Permalink to “getPlayerById()”">​</a></h3><blockquote><p><strong>getPlayerById</strong>(<code>id</code>): <code>StorePlayer</code> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L217" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:217</a></p><p>The online player with runtime id <code>id</code>.</p><p>Null when nobody has it, as the signature always said. It used to assert instead, so asking after a player who had just left took the caller down with it.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id-2" tabindex="-1">id <a class="header-anchor" href="#id-2" aria-label="Permalink to “id”">​</a></h5><p><code>bigint</code></p><p>The runtime id to look up.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>StorePlayer</code> | <code>null</code></p><p>The player, or null when no online player has that id.</p><h4 id="deprecated-1" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated-1" aria-label="Permalink to “Deprecated”">​</a></h4><hr><h3 id="getplayerlist" tabindex="-1">getPlayerList() <a class="header-anchor" href="#getplayerlist" aria-label="Permalink to “getPlayerList()”">​</a></h3><blockquote><p><strong>getPlayerList</strong>(): <code>Map</code>&lt;<code>string</code>, <a href="./../../protocol/classes/PlayerListEntry.html"><code>PlayerListEntry</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L114" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:114</a></p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>Map</code>&lt;<code>string</code>, <a href="./../../protocol/classes/PlayerListEntry.html"><code>PlayerListEntry</code></a>&gt;</p><hr><h3 id="getsessions" tabindex="-1">getSessions() <a class="header-anchor" href="#getsessions" aria-label="Permalink to “getSessions()”">​</a></h3><blockquote><p><strong>getSessions</strong>(): <a href="./PlayerSession.html"><code>PlayerSession</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L137" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:137</a></p><p>The sessions of every online player on the server, in any world: the sessions of the players <a href="#getallplayers">SessionManager.getAllPlayers</a> lists, in the same order. A session is online while <a href="./PlayerSession.html#isconnected">PlayerSession.isConnected</a> says so.</p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./PlayerSession.html"><code>PlayerSession</code></a>[]</p><p>The sessions.</p><hr><h3 id="has" tabindex="-1">has() <a class="header-anchor" href="#has" aria-label="Permalink to “has()”">​</a></h3><blockquote><p><strong>has</strong>(<code>id</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L38" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:38</a></p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id-3" tabindex="-1">id <a class="header-anchor" href="#id-3" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="holdsidentity" tabindex="-1">holdsIdentity() <a class="header-anchor" href="#holdsidentity" aria-label="Permalink to “holdsIdentity()”">​</a></h3><blockquote><p><strong>holdsIdentity</strong>(<code>connection</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L72" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:72</a></p><p>Whether <code>connection</code> still holds the account it reserved, which it stops doing when a later login of the same account replaces it.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="connection-2" tabindex="-1">connection <a class="header-anchor" href="#connection-2" aria-label="Permalink to “connection”">​</a></h5><p><code>ClientConnection</code></p><p>The connection logging in.</p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>False once another login has taken the account, or when it never reserved one.</p><hr><h3 id="kickallplayers" tabindex="-1">kickAllPlayers() <a class="header-anchor" href="#kickallplayers" aria-label="Permalink to “kickAllPlayers()”">​</a></h3><blockquote><p><strong>kickAllPlayers</strong>(<code>reason</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L178" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:178</a></p><p>Kick all players.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="reason" tabindex="-1">reason <a class="header-anchor" href="#reason" aria-label="Permalink to “reason”">​</a></h5><p><code>string</code></p><p>The reason to kick the players.</p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="remove" tabindex="-1">remove() <a class="header-anchor" href="#remove" aria-label="Permalink to “remove()”">​</a></h3><blockquote><p><strong>remove</strong>(<code>id</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L46" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:46</a></p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id-4" tabindex="-1">id <a class="header-anchor" href="#id-4" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="reserveidentity" tabindex="-1">reserveIdentity() <a class="header-anchor" href="#reserveidentity" aria-label="Permalink to “reserveIdentity()”">​</a></h3><blockquote><p><strong>reserveIdentity</strong>(<code>connection</code>, <code>identity</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L62" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:62</a></p><p>Records that a login on <code>connection</code> names <code>identity</code>, without replacing anybody.</p><p>Called once the login has passed the checks that need no world, before the encryption handshake, so that a later login of the same account finds this one while it waits for the client&#39;s answer. A login refused later never displaces anybody: only <a href="#claimidentity">SessionManager.claimIdentity</a> does.</p><h4 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="connection-3" tabindex="-1">connection <a class="header-anchor" href="#connection-3" aria-label="Permalink to “connection”">​</a></h5><p><code>ClientConnection</code></p><p>The connection logging in.</p><h5 id="identity-1" tabindex="-1">identity <a class="header-anchor" href="#identity-1" aria-label="Permalink to “identity”">​</a></h5><p><code>PlayerIdentity</code></p><p>The account its login names.</p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="sessionof" tabindex="-1">sessionOf() <a class="header-anchor" href="#sessionof" aria-label="Permalink to “sessionOf()”">​</a></h3><blockquote><p><strong>sessionOf</strong>(<code>id</code>): <a href="./PlayerSession.html"><code>PlayerSession</code></a> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1fea27be0923ef7ea5f5abcc1fb8179d8c6578fb/packages/prismarine/src/SessionManager.ts#L151" target="_blank" rel="noreferrer">prismarine/src/SessionManager.ts:151</a></p><p>The session of the online player with entity id <code>id</code>.</p><h4 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id-5" tabindex="-1">id <a class="header-anchor" href="#id-5" aria-label="Permalink to “id”">​</a></h5><p><code>bigint</code></p><p>The player&#39;s entity id, which its session holds.</p><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./PlayerSession.html"><code>PlayerSession</code></a> | <code>null</code></p><p>The session, or null when no online player has that id.</p>`,199)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};